using BSL.v41.General.GHelp;
using BSL.v41.General.Networking;
using BSL.v41.Logic.Database;
using BSL.v41.Logic.Database.Account;
using BSL.v41.Logic.Database.Alliance;
using BSL.v41.Logic.Environment.LaserListener;
using BSL.v41.Logic.Environment.LaserMessage.Laser.Node_11;
using BSL.v41.Logic.Environment.LaserMessage.Sepo.Alliance;
using BSL.v41.Supercell.Titan.CommonUtils.Utils;
using BSL.v41.Titan.Mathematical.Data;
using BSL.v41.Tools.LaserCsv;
using BSL.v41.Tools.LaserCsv.Manufacturer.Laser;
namespace BSL.v41.General.NetIsland;
public static class ClubManager
{
 private static readonly object Sync=new();
 private static readonly Dictionary<long,Dictionary<long,ServerConnection>> Requests=new();
 private static readonly Dictionary<long,HashSet<long>> Invites=new();
 private static long _streamId;
 private static long ClubId(AccountModel a)=>Convert.ToInt64(a.GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceId));
 private static Dictionary<long,AllianceMemberEntry> Members(AllianceModel c)=>ToOpenDictionaryHelper.ToAllianceMemberEntryDictionary(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceMemberEntryList));
 private static AllianceModel? Load(long id)=>id>0?Databases.AllianceDatabase.LoadAlliance(id):null;
 public static bool Join(ServerConnection conn,long id,bool invite=false){lock(Sync){var a=conn.GetAccountModel();if(ClubId(a)>0)return false;var c=Load(id);if(c==null)return false;var m=Members(c);if(m.Count>=30)return false;var type=Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceType));var req=Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceRequiredScore));var trophies=Convert.ToInt32(a.GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.Trophies));if(!invite&&(type!=0||trophies<req))return false;if(invite&&(!Invites.TryGetValue(a.GetAccountId(),out var pending)||!pending.Remove(id)))return false;if(m.ContainsKey(a.GetAccountId()))return false;var e=new AllianceMemberEntry{AccountId=a.GetAccountId(),AllianceRoleHelperTable=AllianceRoleHelperTable.Member};m[a.GetAccountId()]=e;c.SetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceMemberEntryList,m);a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceId,id);a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceMemberEntry,e);Requests.Remove(id);Broadcast(c);Response(conn,20);return true;}}
 public static bool Leave(ServerConnection conn,bool kicked=false){lock(Sync){var a=conn.GetAccountModel();var id=ClubId(a);var c=Load(id);if(c==null)return false;var m=Members(c);if(!m.Remove(a.GetAccountId()))return false;a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceId,0L);a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceMemberEntry,new AllianceMemberEntry{AccountId=a.GetAccountId(),AllianceRoleHelperTable=AllianceRoleHelperTable.NonMember});if(m.Count==0){Databases.AllianceDatabase.DeleteAlliance(id);Requests.Remove(id);}else{if(!m.Values.Any(x=>x.AllianceRoleHelperTable==AllianceRoleHelperTable.Leader))m.Values.First().AllianceRoleHelperTable=AllianceRoleHelperTable.Leader;c.SetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceMemberEntryList,m);Broadcast(c);}Response(conn,kicked?81:80);return true;}}
 public static bool Kick(ServerConnection actor,long targetId){lock(Sync){var c=Load(ClubId(actor.GetAccountModel()));if(c==null||targetId==actor.GetAccountModel().GetAccountId())return false;var m=Members(c);if(!m.TryGetValue(actor.GetAccountModel().GetAccountId(),out var ar)||!m.TryGetValue(targetId,out var tr))return false;var role=ar.AllianceRoleHelperTable;var target=tr.AllianceRoleHelperTable;var allowed=role==AllianceRoleHelperTable.Leader||(role==AllianceRoleHelperTable.CoLeader&&target!=AllianceRoleHelperTable.Leader&&target!=AllianceRoleHelperTable.CoLeader)||(role==AllianceRoleHelperTable.Elder&&target==AllianceRoleHelperTable.Member);if(!allowed)return false;var a=Databases.AccountDatabase.LoadAccount(targetId);if(a==null)return false;m.Remove(targetId);a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceId,0L);a.SetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AllianceMemberEntry,new AllianceMemberEntry{AccountId=targetId,AllianceRoleHelperTable=AllianceRoleHelperTable.NonMember});c.SetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceMemberEntryList,m);Broadcast(c);Response(actor,10);return true;}}
 public static bool ChangeRole(ServerConnection actor,long targetId,int value){lock(Sync){if(!Enum.IsDefined(typeof(AllianceRoleHelperTable),value)||value==0||value==2)return false;var c=Load(ClubId(actor.GetAccountModel()));if(c==null)return false;var m=Members(c);if(!m.TryGetValue(actor.GetAccountModel().GetAccountId(),out var ar)||!m.TryGetValue(targetId,out var tr))return false;if(ar.AllianceRoleHelperTable!=AllianceRoleHelperTable.Leader&&ar.AllianceRoleHelperTable!=AllianceRoleHelperTable.CoLeader)return false;if(tr.AllianceRoleHelperTable==AllianceRoleHelperTable.Leader||(ar.AllianceRoleHelperTable==AllianceRoleHelperTable.CoLeader&&tr.AllianceRoleHelperTable==AllianceRoleHelperTable.CoLeader))return false;tr.AllianceRoleHelperTable=(AllianceRoleHelperTable)value;c.SetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceMemberEntryList,m);Broadcast(c);Response(actor,10);return true;}}
 public static bool RequestJoin(ServerConnection requester,long id){lock(Sync){if(ClubId(requester.GetAccountModel())>0)return false;var c=Load(id);if(c==null||Members(c).Count>=30)return false;var type=Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceType));var tr=Convert.ToInt32(requester.GetAccountModel().GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.Trophies));var req=Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceRequiredScore));if(type!=1||tr<req)return false;if(!Requests.TryGetValue(id,out var rs))Requests[id]=rs=new();rs[requester.GetAccountModel().GetAccountId()]=requester;Response(requester,19);return true;}}
 public static bool Respond(ServerConnection actor,long targetId,bool accept){lock(Sync){var id=ClubId(actor.GetAccountModel());var c=Load(id);if(c==null||!Requests.TryGetValue(id,out var rs)||!rs.TryGetValue(targetId,out var requester))return false;var m=Members(c);if(!m.TryGetValue(actor.GetAccountModel().GetAccountId(),out var role)||role.AllianceRoleHelperTable is not (AllianceRoleHelperTable.Leader or AllianceRoleHelperTable.CoLeader or AllianceRoleHelperTable.Elder))return false;rs.Remove(targetId);if(rs.Count==0)Requests.Remove(id);if(!accept){Response(actor,10);return true;}if(!Invites.TryGetValue(targetId,out var pending))Invites[targetId]=pending=new();pending.Add(id);var joined=Join(requester,id,true);if(!joined)pending.Remove(id);return joined;}}
 public static bool Invite(ServerConnection actor,long targetId){lock(Sync){var id=ClubId(actor.GetAccountModel());var c=Load(id);var target=Databases.AccountDatabase.LoadAccount(targetId);if(c==null||target==null||Members(c).Count>=30||!actor.GetAccountModel().GetFriendIds().Contains(targetId)||ClubId(target)>0)return false;var m=Members(c);if(!m.TryGetValue(actor.GetAccountModel().GetAccountId(),out var role)||role.AllianceRoleHelperTable is not (AllianceRoleHelperTable.Leader or AllianceRoleHelperTable.CoLeader or AllianceRoleHelperTable.Elder))return false;if(!Invites.TryGetValue(targetId,out var inv))Invites[targetId]=inv=new();inv.Add(id);Response(actor,10);return true;}}
 public static void Chat(ServerConnection sender,string text){if(string.IsNullOrWhiteSpace(text))return;text=text.Trim();if(text.Length>200)text=text[..200];lock(Sync){var c=Load(ClubId(sender.GetAccountModel()));if(c==null)return;var a=sender.GetAccountModel();var name=a.GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.AvatarName)?.ToString()??"Player";var msg=new AllianceStreamMessage(Interlocked.Increment(ref _streamId),a.GetAccountId(),name,text,LogicTimeUtil.GetTimestamp());foreach(var id in Members(c).Keys)if(IdentifierListener.GetV2LogicGameListenerByAccountId(id))try{IdentifierListener.GetLogicGameListenerByAccountId(id).Send(msg);}catch{}}}
 public static void Search(ServerConnection conn,string query){var list=string.IsNullOrWhiteSpace(query)?Databases.AllianceDatabase.GetRandomAllianceModels(35000):Databases.AllianceDatabase.GetAllianceModelsByName(query);conn.GetMessaging()!.Send(new AllianceListMessage(list.Where(c=>Members(c).Count<30).Take(20).Select(Header).ToList()));}
 public static void Joinable(ServerConnection conn){var tr=Convert.ToInt32(conn.GetAccountModel().GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.Trophies));var list=Databases.AllianceDatabase.GetRandomAllianceModels(tr).Where(c=>Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceType))==0&&Members(c).Count<30).Take(20);conn.GetMessaging()!.Send(new JoinableAllianceListMessage(list.Select(Header).ToList()));}
 public static void Broadcast(AllianceModel c){var id=c.GetAllianceId();var members=Members(c);var header=Header(c);var description=c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceDescription)?.ToString()??"";var full=new AllianceFullEntry();full.SetAllianceDescription(description);full.SetAllianceHeaderEntry(header);full.SetAllianceMembers(members);foreach(var pair in members){if(!IdentifierListener.GetV2LogicGameListenerByAccountId(pair.Key))continue;var a=Databases.AccountDatabase.LoadAccount(pair.Key);if(a==null)continue;var listener=IdentifierListener.GetLogicGameListenerByAccountId(pair.Key);try{var my=new MyAllianceMessage{OnlineMembers=members.Keys.Count(IdentifierListener.GetV2LogicGameListenerByAccountId),AllianceRole=pair.Value.AllianceRoleHelperTable,AllianceHeaderEntry=header};listener.Send(my);var data=new AllianceDataMessage{IsMyAlliance=true,MyAccountId=pair.Key};data.SetAllianceFullEntry(full);listener.Send(data);}catch{}}ToSendAutomizeHelper.SendAllianceStatus(c,-1);} private static AllianceHeaderEntry Header(AllianceModel c){var m=Members(c);var score=m.Keys.Sum(id=>{var a=Databases.AccountDatabase.LoadAccount(id);return a==null?0:Convert.ToInt32(a.GetFieldValueByAccountStructureParameterFromAccountModel(AccountStructure.Trophies));});var h=new AllianceHeaderEntry();h.SetAllianceId(c.GetAllianceId());h.SetAllianceName(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceName)?.ToString()??"");h.SetScore(score);h.SetAllianceType(Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceType)));h.SetAllianceBadgeData(Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceBadgeData)));h.SetRequiredScore(Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceRequiredScore)));h.SetPreferredLanguage(Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceLanguage)));h.SetAllianceRegionData(Convert.ToInt32(c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceRegion)));h.SetNumberOfMembers(m.Count);h.SetIsFamilyType((bool)c.GetFieldValueByAllianceStructureParameterFromAllianceModel(AllianceStructure.AllianceFamilyType));return h;}
 private static void Response(ServerConnection conn,int code){var m=new AllianceResponseMessage();m.IsResponse(code);conn.GetMessaging()!.Send(m);}
}
